export const empty=()=>({version:1,materials:[],suppliers:[],purchases:[],entries:[],proposals:[],employees:[],steps:[],audit:[],quotes:[]});
export class LocalRepository{constructor(storage){if(arguments.length)this.storage=storage;else{try{this.storage=globalThis.localStorage}catch{this.storage=null}}}load(){let raw=this.storage?.getItem('rr-elvira-v1');return raw?this.validate(JSON.parse(raw)):empty()}validate(s){if(!s||s.version!==1||Object.keys(empty()).some(k=>k!=='version'&&!Array.isArray(s[k])))throw Error('Backup incompatível');return s}save(s){this.validate(s);if(!this.storage)throw Error('Armazenamento indisponível. Exporte um backup antes de fechar a página.');this.storage.setItem('rr-elvira-v1',JSON.stringify(s))}}
export {LocalRepository as SessionRepository};
